style.css:
/* Mossy Survivr — surviv.io */

/* swap these colors if you like */
:root {
  --my-sage: #829b78;
  --my-cream: #f5efdf;
  --my-brown: #705c49;
  --my-moss: #536d50;
  --my-wood: #b99570;
}

/* cozy page background */
html,
body {
  background-color: #e8e2d0 !important;
  color: var(--my-brown) !important;
  font-family: "Trebuchet MS", sans-serif !important;
}

/* softer buttons */
button {
  border-radius: 12px !important;
  transition: background-color 0.2s ease,
              transform 0.2s ease !important;
}

/* warm button colors */
button:hover {
  filter: brightness(1.08) !important;
}

/* cozy selection colors */
::selection {
  background: #a9bd91 !important;
  color: #394b36 !important;
}

/* softer scrollbars */
::-webkit-scrollbar {
  width: 10px !important;
}

::-webkit-scrollbar-track {
  background: var(--my-cream) !important;
}

::-webkit-scrollbar-thumb {
  background: var(--my-sage) !important;
  border-radius: 10px !important;
}
